"""Stdlib logging + a tiny metrics shim, replacing the original's singer-python dependency."""

import logging

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s %(name)s - %(levelname)s - %(message)s",
)

LOGGER = logging.getLogger("target_postgres")


class Counter:
    """Minimal stand-in for singer-python's metrics.Counter context manager."""

    def __init__(self, metric: str, tags: dict | None = None):
        self.metric = metric
        self.tags = tags or {}
        self.value = 0

    def increment(self, amount: int = 1) -> None:
        self.value += amount

    def __enter__(self) -> "Counter":
        return self

    def __exit__(self, exc_type, exc, tb) -> bool:
        LOGGER.info(
            'METRIC: {"type": "counter", "metric": "%s", "value": %s, "tags": %s}',
            self.metric,
            self.value,
            self.tags,
        )
        return False

"""CSV row rendering matching the original's COPY FORMAT CSV ESCAPE '\\' semantics (SPEC.md §15).

Every field is JSON-encoded (json.dumps(value, ensure_ascii=False)) except
NULL/falsy-but-not-zero values, which become empty CSV fields.

Quoting is hand-rolled (rather than the stdlib `csv` module) because
Postgres's `COPY ... WITH (FORMAT CSV, ESCAPE '\\')` dialect differs from
what Python's csv.writer produces for a non-default escapechar: Postgres
still *wraps* a field in the quote character whenever it contains the
delimiter/quote/newline, and only the quote character itself is
backslash-escaped inside that wrapping -- csv.writer with
`doublequote=False` instead skips the wrapping quotes entirely and just
backslash-escapes the quote character in place, which COPY would not parse
back correctly.
"""

import json

_NEEDS_QUOTING = (",", '"', "\n", "\r")


def _is_blank(value) -> bool:
    if isinstance(value, bool):
        return not value
    if isinstance(value, (int, float)) and value == 0:
        return False
    return not value


def _field_repr(value) -> str:
    if _is_blank(value):
        return ""
    return json.dumps(value, ensure_ascii=False)


def _csv_field(field: str) -> str:
    if any(ch in field for ch in _NEEDS_QUOTING):
        return '"' + field.replace('"', '\\"') + '"'
    return field


def record_to_csv_row(record: dict, columns: list[str]) -> str:
    """Render a single CSV row (including trailing newline) for `columns`, in order."""
    fields = (_csv_field(_field_repr(record.get(col))) for col in columns)
    return ",".join(fields) + "\n"


def records_to_csv(records: list[dict], columns: list[str]) -> str:
    """Render multiple buffered records into one CSV payload for COPY."""
    return "".join(record_to_csv_row(record, columns) for record in records)

"""Exceptions raised while ingesting Singer messages."""


class TargetPostgresException(Exception):
    """Base class for all target-postgres errors."""


class PrimaryKeyNotFoundException(TargetPostgresException):
    """Raised when a SCHEMA message has no key_properties and primary_key_required is set."""


class TargetSchemaNotFoundException(TargetPostgresException):
    """Raised when a stream's target schema cannot be resolved from config."""


class RecordValidationException(TargetPostgresException):
    """Raised when a RECORD fails JSON Schema validation."""


class InvalidValidationOperationException(TargetPostgresException):
    """Raised when record validation itself fails with a decimal.InvalidOperation."""


class UnsupportedBatchEncodingException(TargetPostgresException):
    """Raised when a BATCH message's encoding.format is anything other than 'arrow'."""


class BatchFlatteningUnsupportedException(TargetPostgresException):
    """Raised when a stream's flattening/inflection config would rename columns away from
    the raw schema property names that a BATCH-sourced Arrow file uses (SPEC.md-style
    by-name column matching can't bridge that gap)."""

