import pyarrow as pa
import pyarrow.ipc as ipc

from target_postgres.arrow_batch import build_adbc_uri, read_manifest_tables, strip_file_uri


class TestStripFileUri:
    def test_strips_file_prefix(self):
        assert strip_file_uri(["file:///tmp/a.arrow"]) == ["/tmp/a.arrow"]

    def test_leaves_plain_paths_unchanged(self):
        assert strip_file_uri(["/tmp/a.arrow"]) == ["/tmp/a.arrow"]

    def test_multiple_entries(self):
        assert strip_file_uri(["file:///a", "/b", "file:///c"]) == ["/a", "/b", "/c"]


class TestReadManifestTables:
    def _write_arrow_file(self, path, data: dict):
        table = pa.table(data)
        with ipc.new_file(str(path), table.schema) as writer:
            writer.write_table(table)
        return path

    def test_reads_single_file(self, tmp_path):
        path = self._write_arrow_file(tmp_path / "a.arrow", {"id": [1, 2], "name": ["a", "b"]})
        table = read_manifest_tables([str(path)])
        assert table.num_rows == 2
        assert table.column_names == ["id", "name"]

    def test_concatenates_multiple_files(self, tmp_path):
        path1 = self._write_arrow_file(tmp_path / "a.arrow", {"id": [1], "name": ["a"]})
        path2 = self._write_arrow_file(tmp_path / "b.arrow", {"id": [2], "name": ["b"]})
        table = read_manifest_tables([str(path1), str(path2)])
        assert table.num_rows == 2
        assert table.column("id").to_pylist() == [1, 2]

    def test_does_not_delete_source_files(self, tmp_path):
        path = self._write_arrow_file(tmp_path / "a.arrow", {"id": [1]})
        read_manifest_tables([str(path)])
        assert path.exists()


class TestBuildAdbcUri:
    def test_basic_uri(self):
        config = {"host": "localhost", "port": 5432, "user": "u", "password": "p", "dbname": "db"}
        assert build_adbc_uri(config) == "postgresql://u:p@localhost:5432/db"

    def test_url_encodes_user_and_password(self):
        config = {"host": "h", "port": 5432, "user": "u@x", "password": "p@ss:word", "dbname": "db"}
        uri = build_adbc_uri(config)
        assert "u%40x" in uri
        assert "p%40ss%3Aword" in uri

    def test_ssl_appends_sslmode(self):
        config = {
            "host": "h",
            "port": 5432,
            "user": "u",
            "password": "p",
            "dbname": "db",
            "ssl": True,
        }
        assert build_adbc_uri(config).endswith("?sslmode=require")

    def test_ssl_string_true_is_not_treated_as_boolean(self):
        config = {
            "host": "h",
            "port": 5432,
            "user": "u",
            "password": "p",
            "dbname": "db",
            "ssl": "true",
        }
        assert "sslmode" not in build_adbc_uri(config)

"""Stream/schema/table/column naming rules (SPEC.md §5, §6).

Column/table identifiers themselves are quoted at the SQL-building layer
(db_sync.py, via psycopg.sql.Identifier) -- this module only computes the
normalized, deduplicated, length-safe *names*.
"""

import re
import uuid

from target_postgres.exceptions import TargetSchemaNotFoundException

MAX_IDENTIFIER_LENGTH = 63
FLATTEN_SEPARATOR = "__"


def underscore(word: str) -> str:
    """Equivalent of inflection.underscore() for the ~2 cases this target needs."""
    word = re.sub(r"([A-Z]+)([A-Z][a-z])", r"\1_\2", word)
    word = re.sub(r"([a-z0-9])([A-Z])", r"\1_\2", word)
    word = word.replace("-", "_")
    return word.lower()


def inflect_name(name: str) -> str:
    """camelCase/PascalCase -> snake_case, collapsing runs of capitals specially.

    Two pre-passes insert an extra underscore before the standard underscore()
    split so that e.g. "HTTPHeader_Value" -> "http_header__value" instead of
    "http_header_value".
    """
    name = re.sub(r"([A-Z]+)_([A-Z][a-z])", r"\1__\2", name)
    name = re.sub(r"([a-z0-9])_([A-Z])", r"\1__\2", name)
    return underscore(name)


def abbreviate(segment: str) -> str:
    """Camelize a path segment then keep only the uppercase "initials".

    Falls back to the first 3 characters if that yields <=1 char.
    """
    camelized = "".join(word[:1].upper() + word[1:] for word in re.split(r"[_\-\s]+", segment) if word)
    initials = "".join(c for c in camelized if c.isupper())
    if len(initials) <= 1:
        return segment[:3]
    return initials


def flatten_key(key_parts: list[str], sep: str = FLATTEN_SEPARATOR) -> str:
    """Join key_parts with sep, abbreviating earlier segments until <=63 chars."""
    parts = list(key_parts)
    name = sep.join(parts)
    if len(name) < MAX_IDENTIFIER_LENGTH:
        return name

    for i in range(len(parts) - 1):
        parts[i] = abbreviate(parts[i])
        name = sep.join(parts)
        if len(name) < MAX_IDENTIFIER_LENGTH:
            return name

    return name[:MAX_IDENTIFIER_LENGTH]


def deduplicate_name(name: str, seen: dict[str, int]) -> str:
    """Resolve a collision against previously-seen names, appending __1, __2, ...

    `seen` is shared/mutated across the whole flatten call, so callers must
    process names in sorted-key order for deterministic results (SPEC.md §5).
    """
    if name not in seen:
        seen[name] = 0
        return name

    seen[name] += 1
    suffix = f"{FLATTEN_SEPARATOR}{seen[name]}"
    truncated = name[: MAX_IDENTIFIER_LENGTH - len(suffix)] + suffix
    while truncated in seen:
        seen[name] += 1
        suffix = f"{FLATTEN_SEPARATOR}{seen[name]}"
        truncated = name[: MAX_IDENTIFIER_LENGTH - len(suffix)] + suffix
    seen[truncated] = 0
    return truncated


def stream_name_to_dict(stream_name: str, separator: str = "-") -> dict:
    """Split a stream-id into catalog/schema/table segments.

    <table>                        -> table only
    <schema>-<table>                -> schema + table
    <catalog>-<schema>-<table...>   -> catalog + schema + table (extra segments
                                        after the 2nd are rejoined with '_')
    """
    segments = stream_name.split(separator)

    if len(segments) == 1:
        return {"catalog_name": None, "schema_name": None, "table_name": segments[0]}
    if len(segments) == 2:
        return {
            "catalog_name": None,
            "schema_name": segments[0],
            "table_name": segments[1],
        }

    return {
        "catalog_name": segments[0],
        "schema_name": segments[1],
        "table_name": "_".join(segments[2:]),
    }


def resolve_target_schema(stream_schema_name: str | None, config: dict) -> str:
    """Resolve the Postgres target schema for a stream (SPEC.md §6)."""
    schema_mapping = config.get("schema_mapping") or {}
    if stream_schema_name and stream_schema_name in schema_mapping:
        return schema_mapping[stream_schema_name]["target_schema"]

    default_target_schema = config.get("default_target_schema")
    if default_target_schema:
        return default_target_schema

    raise TargetSchemaNotFoundException(
        f"Cannot resolve target schema for stream schema segment {stream_schema_name!r}: "
        "no matching schema_mapping entry and no default_target_schema configured"
    )


def resolve_grantees(stream_schema_name: str | None, config: dict):
    """Resolve select-permission grantees for a stream (SPEC.md §6)."""
    schema_mapping = config.get("schema_mapping") or {}
    if stream_schema_name and stream_schema_name in schema_mapping:
        grantees = schema_mapping[stream_schema_name].get("target_schema_select_permissions")
        if grantees:
            return grantees

    return config.get("default_target_schema_select_permissions")


def resolve_indices(stream_schema_name: str | None, table: str, config: dict) -> list[str]:
    """Resolve configured index columns for a stream's table (SPEC.md §11)."""
    schema_mapping = config.get("schema_mapping") or {}
    if stream_schema_name and stream_schema_name in schema_mapping:
        indices = schema_mapping[stream_schema_name].get("indices") or {}
        return indices.get(table, [])
    return []


def safe_table_name(raw_table: str) -> str:
    """Normalize a stream's table segment into a Postgres-safe table name."""
    return raw_table.replace(".", "_").replace("-", "_").lower()


def temp_table_name() -> str:
    return "tmp_" + str(uuid.uuid4()).replace("-", "_")

from target_postgres.schema import column_type, flatten_record, flatten_schema


class TestColumnType:
    def test_object_is_jsonb(self):
        assert column_type({"type": ["object"]}) == "jsonb"

    def test_array_is_jsonb(self):
        assert column_type({"type": ["array"]}) == "jsonb"

    def test_date_time_format(self):
        assert column_type({"type": ["string"], "format": "date-time"}) == "timestamp without time zone"

    def test_time_format(self):
        assert column_type({"type": ["string"], "format": "time"}) == "time without time zone"

    def test_date_format(self):
        assert column_type({"type": ["string"], "format": "date"}) == "date"

    def test_number(self):
        assert column_type({"type": ["number", "null"]}) == "double precision"

    def test_integer_and_string_union_is_ambiguous_varchar(self):
        assert column_type({"type": ["integer", "string"]}) == "character varying"

    def test_integer_small_max(self):
        assert column_type({"type": ["integer"], "maximum": 32767}) == "smallint"

    def test_integer_medium_max(self):
        assert column_type({"type": ["integer"], "maximum": 2147483647}) == "integer"

    def test_integer_large_max(self):
        assert column_type({"type": ["integer"], "maximum": 9223372036854775807}) == "bigint"

    def test_integer_no_max_is_unbounded_numeric(self):
        assert column_type({"type": ["integer"]}) == "numeric"

    def test_integer_max_exceeding_all_bounds_falls_back_to_numeric(self):
        # SPEC.md §4 point 6: original has a fallthrough bug here (leaves
        # character varying); this reimplementation fixes it to numeric.
        assert column_type({"type": ["integer"], "maximum": 10**30}) == "numeric"

    def test_boolean(self):
        assert column_type({"type": ["boolean", "null"]}) == "boolean"

    def test_default_string_no_format(self):
        assert column_type({"type": ["string", "null"]}) == "character varying"

    def test_plain_string_type_not_list(self):
        assert column_type({"type": "string"}) == "character varying"

    def test_no_type_key(self):
        assert column_type({}) == "character varying"


class TestFlattenSchema:
    def test_flat_properties(self):
        properties = {"id": {"type": ["integer"]}, "name": {"type": ["string"]}}
        columns = flatten_schema(properties, {})
        names = {c["name"] for c in columns}
        assert names == {"id", "name"}

    def test_nested_object_flattens_within_max_level(self):
        properties = {
            "address": {
                "type": ["object"],
                "properties": {
                    "city": {"type": ["string"]},
                    "zip": {"type": ["string"]},
                },
            }
        }
        columns = flatten_schema(properties, {"data_flattening_max_level": 1})
        names = {c["name"] for c in columns}
        assert names == {"address__city", "address__zip"}

    def test_nested_object_falls_back_to_jsonb_past_max_level(self):
        properties = {
            "address": {
                "type": ["object"],
                "properties": {"city": {"type": ["string"]}},
            }
        }
        columns = flatten_schema(properties, {"data_flattening_max_level": 0})
        assert len(columns) == 1
        assert columns[0]["name"] == "address"
        assert column_type(columns[0]["schema"]) == "jsonb"

    def test_array_never_recursed_into(self):
        properties = {
            "tags": {
                "type": ["array"],
                "items": {"type": "object", "properties": {"x": {"type": "string"}}},
            }
        }
        columns = flatten_schema(properties, {"data_flattening_max_level": 5})
        assert len(columns) == 1
        assert columns[0]["name"] == "tags"

    def test_underscore_camel_case_fields(self):
        properties = {"HTTPHeader_Value": {"type": ["string"]}}
        columns = flatten_schema(properties, {"underscore_camel_case_fields": True})
        assert columns[0]["name"] == "http_header__value"

    def test_dedup_suffix_on_name_collision(self):
        properties = {
            "a__b": {"type": ["string"]},
            "a": {
                "type": ["object"],
                "properties": {"b": {"type": ["string"]}},
            },
        }
        columns = flatten_schema(properties, {"data_flattening_max_level": 1})
        names = sorted(c["name"] for c in columns)
        assert names == ["a__b", "a__b__1"]


class TestFlattenRecord:
    def test_extracts_flat_values(self):
        properties = {"id": {"type": ["integer"]}, "name": {"type": ["string"]}}
        columns = flatten_schema(properties, {})
        record = {"id": 1, "name": "Ada"}
        assert flatten_record(record, columns) == {"id": 1, "name": "Ada"}

    def test_missing_keys_are_omitted(self):
        properties = {"id": {"type": ["integer"]}, "name": {"type": ["string"]}}
        columns = flatten_schema(properties, {})
        record = {"id": 1}
        assert flatten_record(record, columns) == {"id": 1}

    def test_nested_values_extracted_by_path(self):
        properties = {
            "address": {
                "type": ["object"],
                "properties": {"city": {"type": ["string"]}},
            }
        }
        columns = flatten_schema(properties, {"data_flattening_max_level": 1})
        record = {"address": {"city": "Berlin"}}
        assert flatten_record(record, columns) == {"address__city": "Berlin"}

    def test_object_past_max_level_passed_through_raw(self):
        properties = {
            "address": {
                "type": ["object"],
                "properties": {"city": {"type": ["string"]}},
            }
        }
        columns = flatten_schema(properties, {"data_flattening_max_level": 0})
        record = {"address": {"city": "Berlin"}}
        assert flatten_record(record, columns) == {"address": {"city": "Berlin"}}

import pytest

from target_postgres.db_sync import DbSync
from target_postgres.exceptions import BatchFlatteningUnsupportedException


def _stream_schema_message(properties, key_properties=("id",)):
    return {
        "stream": "public-things",
        "key_properties": list(key_properties),
        "schema": {"properties": properties},
    }


class TestCheckBatchFlatteningSupported:
    def test_flat_schema_is_supported(self):
        message = _stream_schema_message({"id": {"type": ["integer"]}, "name": {"type": ["string"]}})
        db_sync = DbSync({"default_target_schema": "public"}, message)
        db_sync._check_batch_flattening_supported()  # should not raise

    def test_metadata_columns_are_ignored(self):
        message = _stream_schema_message({"id": {"type": ["integer"]}})
        config = {"default_target_schema": "public", "add_metadata_columns": True}
        db_sync = DbSync(config, message)
        db_sync._check_batch_flattening_supported()  # should not raise

    def test_nested_flattening_raises(self):
        message = _stream_schema_message(
            {
                "id": {"type": ["integer"]},
                "address": {
                    "type": ["object"],
                    "properties": {"city": {"type": ["string"]}},
                },
            }
        )
        config = {"default_target_schema": "public", "data_flattening_max_level": 1}
        db_sync = DbSync(config, message)
        with pytest.raises(BatchFlatteningUnsupportedException):
            db_sync._check_batch_flattening_supported()

    def test_nested_object_without_flattening_is_supported(self):
        # data_flattening_max_level defaults to 0, so the nested object stays a single
        # jsonb column named exactly like the raw property -- no rename, BATCH-safe.
        message = _stream_schema_message(
            {
                "id": {"type": ["integer"]},
                "address": {
                    "type": ["object"],
                    "properties": {"city": {"type": ["string"]}},
                },
            }
        )
        db_sync = DbSync({"default_target_schema": "public"}, message)
        db_sync._check_batch_flattening_supported()  # should not raise

    def test_camel_case_inflection_raises(self):
        message = _stream_schema_message({"HTTPHeader": {"type": ["string"]}}, key_properties=())
        config = {"default_target_schema": "public", "underscore_camel_case_fields": True}
        db_sync = DbSync(config, message)
        with pytest.raises(BatchFlatteningUnsupportedException):
            db_sync._check_batch_flattening_supported()


class TestUpsertSourceColumns:
    def test_defaults_to_all_columns(self):
        message = _stream_schema_message({"id": {"type": ["integer"]}, "name": {"type": ["string"]}})
        db_sync = DbSync({"default_target_schema": "public"}, message)
        assert db_sync.column_order() == sorted(["id", "name"])

import json

import pytest

import target_postgres.target as target_module
from target_postgres.schema import flatten_schema


class FakeDbSync:
    """Stands in for db_sync.DbSync so batching tests never touch a real DB."""

    instances = []

    def __init__(self, config, stream_schema_message):
        self.config = config
        self.stream = stream_schema_message["stream"]
        self.key_properties = stream_schema_message.get("key_properties") or []
        self.columns = flatten_schema(stream_schema_message["schema"].get("properties", {}), config)
        self.flush_calls = []
        self.batch_calls = []
        FakeDbSync.instances.append(self)

    def create_schema_if_not_exists(self):
        pass

    def sync_table(self):
        pass

    def primary_key_string(self, record, fallback_index):
        if not self.key_properties:
            return f"RID-{fallback_index}"
        return ",".join(str(record.get(kp)) for kp in self.key_properties)

    def flush(self, records):
        self.flush_calls.append(dict(records))
        return {"inserts": len(records), "updates": 0, "size_bytes": 0}

    def load_rows_from_arrow_files(self, file_paths):
        self.batch_calls.append(list(file_paths))
        return {"inserts": len(file_paths), "updates": 0, "size_bytes": 0}


@pytest.fixture(autouse=True)
def patch_db_sync(monkeypatch):
    FakeDbSync.instances = []
    monkeypatch.setattr(target_module, "DbSync", FakeDbSync)
    yield


def _schema_line(stream, key_properties=("id",)):
    return json.dumps(
        {
            "type": "SCHEMA",
            "stream": stream,
            "key_properties": list(key_properties),
            "schema": {
                "properties": {
                    "id": {"type": ["integer"]},
                    "name": {"type": ["string"]},
                }
            },
        }
    )


def _record_line(stream, record_id):
    return json.dumps(
        {
            "type": "RECORD",
            "stream": stream,
            "record": {"id": record_id, "name": f"n{record_id}"},
        }
    )


def _state_line(value):
    return json.dumps({"type": "STATE", "value": value})


def _batch_line(stream, manifest, encoding_format="arrow"):
    return json.dumps(
        {
            "type": "BATCH",
            "stream": stream,
            "encoding": {"format": encoding_format},
            "manifest": manifest,
        }
    )


class TestBatching:
    def test_40_records_batch_size_20_flushes_twice(self):
        lines = [_schema_line("users")]
        lines += [_record_line("users", i) for i in range(40)]

        target_module.persist_lines({"batch_size_rows": 20}, lines)

        db_sync = FakeDbSync.instances[0]
        assert len(db_sync.flush_calls) == 2
        assert len(db_sync.flush_calls[0]) == 20
        assert len(db_sync.flush_calls[1]) == 20

    def test_fewer_records_than_batch_size_flushes_once_at_eof(self):
        lines = [_schema_line("users")]
        lines += [_record_line("users", i) for i in range(5)]

        target_module.persist_lines({"batch_size_rows": 20}, lines)

        db_sync = FakeDbSync.instances[0]
        assert len(db_sync.flush_calls) == 1
        assert len(db_sync.flush_calls[0]) == 5

