        # stream "a" hits batch_size_rows=2 first
        lines.append(_record_line("a", 1))
        lines.append(_record_line("a", 2))
        lines.append(_state_line({"bookmarks": {"a": {"pos": 2}, "b": {"pos": 0}}}))
        lines.append(_record_line("b", 1))

