        ]
        persist_lines(config, lines2)

        columns, rows = fetch_rows(pg_connect, "public", "gizmos")
        batched_idx = columns.index("_sdc_batched_at")
        assert rows[0][batched_idx] >= first_batched_at


class TestArrowErrorHandling:
